3	namespace App\Services\Cache;
4	
5	use Closure;
6	use DateTimeInterface;
7	use Illuminate\Contracts\Cache\LockTimeoutException;
8	use Illuminate\Support\Facades\Cache;
9	use Throwable;
10	
11	/**
12	 * Single-flight cache regeneration helper.
13	 *
14	 * Wraps Laravel's Cache::remember with a Cache::lock so that under concurrent
15	 * load only one request rebuilds an expired value while others wait and read
16	 * the freshly-filled cache. Models the proven pattern in
17	 * SiteCacheService::getPublicSitePayload.
18	 *
19	 * Use this for any cached value that:
20	 *   - is hot (likely to be requested concurrently when it expires), AND
21	 *   - is expensive to regenerate (multiple DB queries, joins, external calls).
22	 *
23	 * Two methods, depending on whether the closure can return null:
24	 *   - rememberLocked()         — closures that always return a non-null value
25	 *   - rememberLockedNullable() — closures that can return null (e.g. lookups that
26	 *                                may not find a row); uses a sentinel so cached
27	 *                                nulls survive across requests instead of triggering
28	 *                                a fresh DB hit each time.
29	 */
30	class CacheLockService
31	{
32	    /**
33	     * Sentinel cached by rememberLockedNullable when a closure returns null,
34	     * so the cache layer can distinguish "key absent" from "computed, was null".
35	     * Chosen as an unlikely-to-collide string rather than a constant object so
36	     * it survives Redis (de)serialisation cleanly.
37	     */
38	    private const NULL_SENTINEL = '__cache_lock_null_sentinel__';
39	
40	    /**
41	     * Get the value at $key, or compute it via $callback under a single-flight lock.
42	     *
43	     * @param  string  $key  Cache key (the lock key is auto-derived as 'lock:'.$key)
44	     * @param  DateTimeInterface|int  $ttl  Same TTL semantics as Cache::remember (DateTime or seconds)
45	     * @param  Closure(): mixed  $callback  Closure that produces the value on miss; must not return null
46	     * @param  int  $lockSeconds  How long the lock is held before auto-expiring (must exceed worst-case closure runtime)
47	     * @param  int  $blockSeconds  How long a waiting request blocks for the lock before falling through
48	     */
49	    public function rememberLocked(
50	        string $key,
51	        DateTimeInterface|int $ttl,
52	        Closure $callback,
53	        int $lockSeconds = 10,
54	        int $blockSeconds = 5,
55	    ): mixed {
56	        // Fast path: value already cached, no lock needed.
57	        $cached = Cache::get($key);
58	        if ($cached !== null) {
59	            return $cached;
60	        }
61	
62	        // Cache miss — acquire a per-key fill lock so only one process rebuilds.
63	        $lock = Cache::lock('lock:'.$key, $lockSeconds);
64	
65	        try {
66	            $lock->block($blockSeconds);
67	        } catch (LockTimeoutException) {
68	            // Another process is filling the cache but took too long.
69	            // Return whatever is now cached, or fall through to compute as a last resort
70	            // so the user never gets nothing back. The stampede risk on this edge case
71	            // is bounded to requests that arrive in the timeout window.
72	            $warm = Cache::get($key);
73	            if ($warm !== null) {
74	                return $warm;
75	            }
76	
77	            return $callback();
78	        }
79	
80	        try {
81	            // Double-check: another process may have filled the cache while we waited.
82	            $rechecked = Cache::get($key);
83	            if ($rechecked !== null) {
84	                return $rechecked;
85	            }
86	
87	            $value = $callback();
88	            Cache::put($key, $value, $ttl);
89	
90	            return $value;
91	        } finally {
92	            // Always release — even if the closure threw — so we don't hold the lock
93	            // for its full TTL after a failure.
94	            try {
95	                $lock->release();
96	            } catch (Throwable) {
97	                // Lock already released or driver doesn't support release-after-expiry; ignore.
98	            }
99	        }
100	    }
101	
102	    /**
103	     * Like rememberLocked, but the callback may return null. Null results are cached
104	     * as a sentinel so subsequent reads return null without re-running the callback.
105	     *
106	     * @param  string  $key  Cache key
107	     * @param  DateTimeInterface|int  $ttl  TTL for non-null values
108	     * @param  Closure(): mixed  $callback  May return null. Must not return the sentinel string.
109	     * @param  DateTimeInterface|int|null  $nullTtl  TTL when caching a null result.
110	     *                                               Defaults to $ttl when null. For negative-cache use cases, pass an explicit
111	     *                                               shorter duration (e.g. 30s) so a "not found" lookup retries sooner once the
112	     *                                               underlying row may have appeared.
113	     */
114	    public function rememberLockedNullable(
115	        string $key,
116	        DateTimeInterface|int $ttl,
117	        Closure $callback,
118	        DateTimeInterface|int|null $nullTtl = null,
119	        int $lockSeconds = 10,
120	        int $blockSeconds = 5,
121	    ): mixed {
122	        $cached = Cache::get($key);
123	        if ($cached === self::NULL_SENTINEL) {
124	            return null;
125	        }
126	        if ($cached !== null) {
127	            return $cached;
128	        }
129	
130	        $lock = Cache::lock('lock:'.$key, $lockSeconds);
131	
132	        try {
133	            $lock->block($blockSeconds);
134	        } catch (LockTimeoutException) {
135	            $warm = Cache::get($key);
136	            if ($warm === self::NULL_SENTINEL) {
137	                return null;
138	            }
139	            if ($warm !== null) {
140	                return $warm;
141	            }
142	
143	            return $callback();
144	        }
145	
146	        try {
147	            $rechecked = Cache::get($key);
148	            if ($rechecked === self::NULL_SENTINEL) {
149	                return null;
150	            }
151	            if ($rechecked !== null) {
152	                return $rechecked;
153	            }
154	
155	            $value = $callback();
156	            if ($value === self::NULL_SENTINEL) {
157	                throw new \LogicException('Closure returned the cache null sentinel; this value is reserved.');
158	            }
159	            if ($value === null) {
160	                Cache::put($key, self::NULL_SENTINEL, $nullTtl ?? $ttl);
161	            } else {
162	                Cache::put($key, $value, $ttl);
163	            }
164	
165	            return $value;
166	        } finally {
167	            try {
168	                $lock->release();
169	            } catch (Throwable) {
170	                // ignore
171	            }
172	        }
173	    }
174	}
